def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]

    gray = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 8]
    clues = [(r, c) for r in range(h) for c in range(w)
             if grid[r][c] not in (0, 8)]
    if not gray or not clues:
        return out

    # The gray drawing is made of equal square tiles.
    runs = []
    for r in range(h):
        c = 0
        while c < w:
            if grid[r][c] == 8:
                start = c
                while c < w and grid[r][c] == 8:
                    c += 1
                runs.append(c - start)
            else:
                c += 1
    for c in range(w):
        r = 0
        while r < h:
            if grid[r][c] == 8:
                start = r
                while r < h and grid[r][c] == 8:
                    r += 1
                runs.append(r - start)
            else:
                r += 1

    import math
    tile = 0
    for length in runs:
        tile = math.gcd(tile, length)
    if tile == 0:
        return out

    # Read the small colored pattern and rotate it clockwise.
    r0 = min(r for r, c in clues)
    r1 = max(r for r, c in clues)
    c0 = min(c for r, c in clues)
    c1 = max(c for r, c in clues)
    key = [[0] * (c1 - c0 + 1) for _ in range(r1 - r0 + 1)]
    for r, c in clues:
        key[r - r0][c - c0] = grid[r][c]

    kh, kw = len(key), len(key[0])
    rotated = [[0] * kh for _ in range(kw)]
    for r in range(kh):
        for c in range(kw):
            rotated[c][kh - 1 - r] = key[r][c]

    gr0 = min(r for r, c in gray)
    gc0 = min(c for r, c in gray)
    tiles = {}
    for r, c in gray:
        y = (r - gr0) // tile
        x = (c - gc0) // tile
        tiles[(y, x)] = True

    colors = {}
    for y, x in tiles:
        if y < len(rotated) and x < len(rotated[0]):
            colors[(y, x)] = rotated[y][x]

    # When a complete colored row expands into a matching gray rectangle,
    # continue that row's color through the rectangle.
    for y in range(len(rotated) - 1):
        x = 0
        while x < len(rotated[0]):
            color = rotated[y][x]
            if color == 0:
                x += 1
                continue
            end = x + 1
            while end < len(rotated[0]) and rotated[y][end] == color:
                end += 1
            if end - x >= 2:
                yy = y + 1
                while yy < len(rotated) and all(
                    (yy, xx) in tiles for xx in range(x, end)
                ):
                    if all((yy, xx) in tiles for xx in range(x, end)):
                        for xx in range(x, end):
                            colors[(yy, xx)] = color
                    yy += 1
            x = end

    for (y, x), color in colors.items():
        if color == 0:
            continue
        top = gr0 + y * tile
        left = gc0 + x * tile
        for r in range(top, min(top + tile, h)):
            for c in range(left, min(left + tile, w)):
                if grid[r][c] == 8:
                    out[r][c] = color
    return out
